export const BAY={color:1191995,roughness:.05,reflect:1.3,tile:96,size:256,waves:[[2,1,.035,0],[3,-2,.03,1.7],[5,2,.03,4.1],[4,-5,.025,2.3],[8,3,.02,5.2],[7,-8,.02,.9]]},HAZE={near:0,far:6e4};export function hazeAt(t,o=HAZE){return Math.min(1,Math.max(0,(t-o.near)/(o.far-o.near)))}export function rippleSlope(t,o,n=BAY.waves){let a=0,c=0;for(const[s,r,e,p]of n){const u=Math.hypot(s,r),h=e*Math.cos(2*Math.PI*(s*t+r*o)+p);a+=h*s/u,c+=h*r/u}return[a,c]}export function maxTilt(t=BAY.waves){return Math.atan(t.reduce((o,n)=>o+n[2],0))}export function meanSquareSlope(t=BAY.waves){return t.reduce((o,n)=>o+n[2]*n[2]/2,0)}export function rippleNormals(t=BAY.size,o=BAY.waves){const n=new Uint8Array(t*t*4);for(let a=0;a<t;a++)for(let c=0;c<t;c++){const[s,r]=rippleSlope(c/t,a/t,o),e=Math.hypot(s,r,1),p=(a*t+c)*4;n[p]=Math.round((-s/e*.5+.5)*255),n[p+1]=Math.round((-r/e*.5+.5)*255),n[p+2]=Math.round((1/e*.5+.5)*255),n[p+3]=255}return n}export function glintTilt(t,o,n){const a=r=>{const e=Math.hypot(...r);return r.map(p=>p/e)},c=a(t.map((r,e)=>r-o[e])),s=a(a(n).map((r,e)=>r+c[e]));return Math.acos(Math.min(1,Math.max(-1,s[1])))}
